def keep_research_for_pilot_schools(apps, schema_editor):
    """Schools already running a study keep their research tools after the flag is introduced."""

    School = apps.get_model("lab", "School")
    PilotStudy = apps.get_model("lab", "PilotStudy")
    ResearchSurveyResponse = apps.get_model("lab", "ResearchSurveyResponse")
    school_ids = set(PilotStudy.objects.values_list("school_id", flat=True)) | set(
        ResearchSurveyResponse.objects.values_list("school_id", flat=True)
    )
    School.objects.filter(pk__in=school_ids).update(research_enabled=True)


